operation.add:
if ($this->config->get('module_bonus_reward_status') && $this->config->get('module_bonus_reward_method') == 'cart') {
	if ($this->config->get('module_bonus_reward_calculation_source') == 'category') {
		$this->load->model('extension/module/bonus_reward');

		$main_category = $this->config->get('module_bonus_reward_category_method');
		$category_id = $this->model_extension_module_bonus_reward->getProductCategory($product['product_id'], $main_category);

		$bonus_reward_config = $this->config->get('module_bonus_reward_category');
		$config_bonus_reward = isset($bonus_reward_config[$category_id]) ? $bonus_reward_config[$category_id] : 0;
	} else {
		$bonus_reward_config = $this->config->get('module_bonus_reward_manufacturer');
		$config_bonus_reward = isset($bonus_reward_config[$product['manufacturer_id']]) ? $bonus_reward_config[$product['manufacturer_id']] : 0;
	}

	if (!empty($config_bonus_reward['customer_group'][$order_data['customer_group_id']])) {
		$product['reward'] = (int)($product['price'] * $product['quantity'] * ($config_bonus_reward['customer_group'][$order_data['customer_group_id']] / 100));
	} else {
		$product['reward'] = '';
	}
} else {
	$product['reward'] = $product['reward'];
}
